  { lhs = "<leader>gC", name = "Go: конструктор New…", doc = "Для struct под курсором пишет New<Тип>(поля…) *<Тип> после объявления типа. Поля-ключевые слова Go получают суффикс _ (type → type_)." },
  { lhs = "<leader>gD", name = "Go: документация", doc = "Вставляет комментарий-заготовку «// Имя … TODO» над функцией или методом под курсором (в формате godoc)." },
