  { lhs = "<leader>gp", name = "Go: структура пакета", doc = "Outline пакета: функции, типы, методы списком с переходом (go.nvim :GoPkgOutline)." },
  { lhs = "<leader>gA", name = "Go: тесты для всех функций файла", doc = "Создаёт заготовки тестов для каждой функции файла через gotests (go.nvim :GoAddAllTest)." },
  { lhs = "<leader>gV", name = "Go: go vet", doc = "Запускает go vet ./... из папки файла в плавающем терминале." },
