  { lhs = "<leader>gO", name = "Go: что вызывает функция", doc = "Call hierarchy (gopls): список функций, которые вызывает функция под курсором." },
  { lhs = "<leader>gJ", mode = "x", name = "Go: JSON → struct", doc = "Выдели JSON в визуальном режиме, введи имя типа — получишь struct с json-тегами (go.nvim :GoJson2Struct)." },
